import React from 'react'
import axios from 'axios'
import { useState } from 'react'
import { useNavigate } from 'react-router-dom'
import Success from '../../success'

const Login = () => {
  const [userName, setUserName] = useState("");
  const [password, setPassword] = useState("");
  const [user, setUser] = useState(null);
  const navigate = useNavigate();

  const handleLogin = async () => {
    try {
        let userData = await axios.get(`http://localhost:5000/students/${userName}`);
    if (userData.data.password === password) {
    //   navigate("/dashboard");
    setUser(userData.data);
} else {
    alert("Invalid username or password");
}
} catch (error) {
    alert("An error occurred while logging in");
}

};

if (user) {
  return <Success name={user.fullName} type="logged in" />;
}

  return (
    <div>
      <h1>Welcome to the Login Page</h1>
      <h3>Enter your username and password</h3>
      <input
        type="text"
        placeholder="Username"
        value={userName}
        onChange={(e) => setUserName(e.target.value)}
      />
      <input
        type="password"
        placeholder="Password"
        value={password}
        minLength={6}          // ✅ minimum length
        maxLength={12}         // ✅ maximum length
        pattern="^(?=.*[A-Z])(?=.*\d).+$"  // ✅ format rule
        title="Password must contain at least 1 uppercase letter and 1 number"
        onChange={(e) => setPassword(e.target.value)}
      />
      <button onClick={handleLogin}>Login</button>
      <button onClick={() => navigate("/signup")}>Go to Signup</button>
      <button onClick={() => navigate("/")}>Back to Home</button>
    </div>
  )
}

export default Login
